import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("score lines", () => {
  test("score lines", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-01");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    await ui.setSetting(pg_uma, "terms", "1");
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "5000.00"}));
    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(true);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.claimAction(pg_vic, c_ada_0, "settle")).toBe(true);
    await ui.refresh(pg_uma);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    await ui.setToday(pg_uma, "2026-03-02");
    await ui.setSetting(pg_uma, "score-log", "on");
    await ui.setSetting(pg_uma, "score-mid", "0");
    await ui.setSetting(pg_uma, "score-high", "1");
    await ui.setToday(pg_uma, "2026-03-03");
    const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "2500.00"}));
    expect(await ui.claimAction(pg_uma, c_ben_0, "open")).toBe(true);
    await ui.refresh(pg_vic);
    expect(await ui.claimAction(pg_vic, c_ben_0, "settle")).toBe(true);
    await ui.refresh(pg_uma);
    await ui.setToday(pg_uma, "2026-03-04");
    await ui.setSetting(pg_uma, "score-log", "");
    await ui.setToday(pg_uma, "2026-03-05");
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-score")).toHaveText("0");
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-band")).toHaveText("MID");
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-snapshot-line")).toHaveText(["2026-03-01 502.00", "2026-03-02 502.00", "2026-03-03 502.00", "2026-03-04 502.00"]);
    await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-score")).toHaveText("5");
    await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-band")).toHaveText("HIGH");
    await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-snapshot-line")).toHaveText(["2026-03-01 0.00", "2026-03-02 0.00", "2026-03-03 500.00", "2026-03-04 500.00"]);
    await ui.expectAudit(sheet, [
      `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00`,
      `RATE_SET sheet=${sheet} by=uma grade=B rate=20.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ben grade=B`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=terms value=1`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=5000.00 date=2026-03-01`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=5000.00 date=2026-03-01`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=5000.00 due-total=500.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=5000.00 due-total=500.00 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=5010.00 due-total=501.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=5010.00 due-total=501.00 overdue-total=0.00`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ada amount=5000.00 date=2026-03-01 number=FY2026-1 due=500.00`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=20.00`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=5010.00 due-total=502.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=5010.00 due-total=502.00 overdue-total=0.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ada due-total=502.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ben due-total=0.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=score-log value=on`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=score-mid value=0`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=score-high value=1`,
      `SCORE sheet=${sheet} by=uma name=Ada score=5`,
      `SCORE sheet=${sheet} by=uma name=Ben score=0`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ada due-total=502.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ben due-total=0.00`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=5010.00 due-total=502.00 overdue-total=2.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=5010.00 due-total=502.00 overdue-total=2.00`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ben amount=2500.00 date=2026-03-03`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ben amount=2500.00 date=2026-03-03`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=2500.00 due-total=500.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=7510.00 due-total=1002.00 overdue-total=2.00`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ben amount=2500.00 date=2026-03-03 number=FY2026-2 due=500.00`,
      `SCORE sheet=${sheet} by=uma name=Ada score=0`,
      `SCORE sheet=${sheet} by=uma name=Ben score=5`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ada due-total=502.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ben due-total=500.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=score-log value=`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ada due-total=502.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ben due-total=500.00`
    ]);
  });
  test("score lines scenario 1", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-04-05");
    await ui.setSetting(pg_uma, "terms", "7");
    await ui.setSetting(pg_uma, "late-pct", "5.00");
    await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
    await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
    await ui.setSetting(pg_uma, "terms-C", "3");
    await ui.setSetting(pg_uma, "perm-open", "steward");
    await ui.setSetting(pg_uma, "grace-days", "0");
    await ui.setSetting(pg_uma, "entry-date", "2026-03-01");
    expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
    expect(await ui.addHoliday(pg_uma, "2026-03-16")).toBe(true);
    expect(await ui.setSettingDated(pg_uma, "rounding", "half-even", "2026-03-10", "half-even")).toBe(true);
    await ui.setSetting(pg_uma, "review-threshold", "1.50");
    await ui.setSetting(pg_uma, "review-sla", "5");
    await ui.setSetting(pg_uma, "proof-kinds", "receipt");
    await ui.setSetting(pg_uma, "score-mid", "0");
    await ui.setSetting(pg_uma, "score-high", "5");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00"})).toBe(true);
